bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
expected=create-videobot:invoice-only-receipts-9b1075b0
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
test "$(docker inspect "$cid" --format '{{.Image}}')" = "$(docker image inspect "$expected" --format '{{.Id}}')" || exit 42
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createGateOwner} from './owner/gateOwner.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
const env=process.env;
if(env.VIDEOBOT_DB_NAME!=='videobot'||env.VIDEO_SALE_MODE!=='invoice')throw Error('VIDEO_RUNTIME_MISMATCH');
const pool=new pg.Pool({host:env.VIDEOBOT_DB_HOST,user:env.VIDEOBOT_DB_USER,database:env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
const net=createCreatorTelegramFetch();
try {
 const r=(await pool.query("SELECT l.listing_id,l.revision,l.status,l.seller_user_id,l.title,l.description,l.price_stars,l.thumbnail_file_id,l.sample_file_id,l.paid_video_file_id,r.sale_mode,r.status AS receipt_status,r.topic_id,r.free_message_ids,r.paid_message_id FROM videobot_listings l JOIN videobot_post_receipts r ON r.listing_id=l.listing_id WHERE r.delivery_key='v26nov24invoice:1'")).rows;
 if(r.length!==1)throw Error('VIDEO_EXISTING_RECEIPT_NOT_UNIQUE');
 const x=r[0],sampleIds=x.free_message_ids?.map(Number);
 if(x.status!=='published'||x.receipt_status!=='sent'||x.sale_mode!=='invoice'||
   x.listing_id!=='v26nov24invoice'||Number(x.revision)!==1||
   sampleIds?.length!==2||!Number.isSafeInteger(Number(x.paid_message_id))||
   sampleIds.includes(Number(x.paid_message_id))||
   !x.thumbnail_file_id||!x.sample_file_id||!x.paid_video_file_id||
   x.thumbnail_file_id===x.paid_video_file_id||
   x.sample_file_id===x.paid_video_file_id)throw Error('VIDEO_RECEIPT_INVALID');
 const oldBuyer=(await pool.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger p JOIN videobot_listings prev ON p.listing_id=prev.listing_id WHERE p.kind='paid' AND prev.seller_user_id=$1 AND prev.paid_video_file_id=$2",[x.seller_user_id,x.paid_video_file_id])).rows[0].n;
 if(oldBuyer!==1)throw Error('VIDEO_HISTORICAL_BUYER_UNVERIFIED');
 const api=createTelegramBotApi({token:readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000});
 const owner=await createGateOwner({pool,telegramApi:api});
 const topic=await owner.getVerifiedVideoTopic({purpose:'video_sale',sellerId:String(x.seller_user_id),listingId:x.listing_id});
 if(topic?.verified!==true||topic.enabled!==true||topic.board!=='video_chat'||topic.purpose!=='video_sale'||
  topic.id!==Number(x.topic_id)||!Number.isSafeInteger(topic.chatId)||
  !Number.isSafeInteger(topic.threadId)||topic.chatId>=0)throw Error('VIDEO_TARGET_NOT_VERIFIED');
 const caption=x.title+(x.description?'\n'+x.description:'');
 if(caption.length>1024||caption.trim().length<1)throw Error('VIDEO_CAPTION_INVALID');
 const purchaseData='vid:buy:'+x.listing_id+':'+x.revision;
 if(purchaseData.length>64)throw Error('VIDEO_CALLBACK_TOO_LONG');
 const markup={inline_keyboard:[[{text:'⭐ '+x.price_stars+' Starsで本編を購入',callback_data:purchaseData}]]};
 const rich={blocks:[{type:'collage',blocks:[
  {type:'photo',photo:{type:'photo',media:x.thumbnail_file_id,has_spoiler:true}},
  {type:'video',video:{type:'video',media:x.sample_file_id,has_spoiler:true}}
 ],caption:{text:caption}}]};
 const token=readPrivateToken(env.VIDEOBOT_TELEGRAM_TOKEN_FILE);
 const res=await net.fetch('https://api.telegram.org/bot'+token+'/editMessageText',{
  method:'POST',headers:{'content-type':'application/json'},
  body:JSON.stringify({chat_id:topic.chatId,message_id:Number(x.paid_message_id),rich_message:rich,reply_markup:markup}),
  signal:AbortSignal.timeout(25000),redirect:'error'});
 const j=await res.json();
 const msg=j?.result,blocks=msg?.rich_message?.blocks;
 const collage=Array.isArray(blocks)?blocks.find(b=>b.type==='collage'):null;
 const actual=msg?.reply_markup?.inline_keyboard?.[0]?.[0];
 const ok=j.ok===true&&msg?.message_id===Number(x.paid_message_id)&&
   msg?.chat?.id===topic.chatId&&!msg?.media_group_id&&
   collage?.blocks?.length===2&&
   collage.blocks[0].type==='photo'&&collage.blocks[1].type==='video'&&
   collage?.caption?.text===caption&&
   actual?.callback_data===purchaseData&&actual?.text===markup.inline_keyboard[0][0].text;
 let reason='UNKNOWN';
 const d=String(j.description??'').toLowerCase();
 if(j.ok===true)reason='OK';
 else if(d.includes('message is not modified'))reason='NOT_MODIFIED';
 else if(d.includes('not found'))reason='MESSAGE_NOT_FOUND';
 else if(d.includes('rich'))reason='RICH_REJECTED';
 else if(d.includes('edit'))reason='EDIT_REJECTED';
 else if(d.includes('media'))reason='MEDIA_INVALID';
 console.log('IN_PLACE_RICH_EDIT='+JSON.stringify({http:res.status,telegramOk:j.ok===true,reason,editAcknowledged:j.ok===true,richBlocks:blocks?.map(b=>b.type)??[],hasExactCaption:collage?.caption?.text===caption,hasOneTapCallback:actual?.callback_data===purchaseData,sameOriginalMessage:msg?.message_id===Number(x.paid_message_id),verified:ok,historicalBuyerUnchanged:true}));
 if(!ok)throw Error('EXISTING_MESSAGE_RICH_EDIT_NOT_VERIFIED_KEEP_ALL_OLD_MEDIA_AND_BUTTON');
}finally{await net.close();await pool.end()}
NODE
